  position: relative;
  flex: none;
  width: calc(var(--cc-font) + 2px);
  height: calc(var(--cc-font) + 2px);
  overflow: hidden;
}

.call-chip__glyph {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  opacity: 0;
  transform: translateY(70%);
  filter: blur(3px);
}

.call-chip__glyph[data-state='in'] {
  opacity: 1;
  transform: none;
  filter: blur(0);
  transition:
    opacity 240ms var(--cc-ease-out),
    transform 240ms var(--cc-ease-out),
    filter 240ms var(--cc-ease-out);
}

.call-chip__glyph[data-state='out'] {
  transform: translateY(-70%);
  transition:
    opacity 160ms var(--cc-ease-out),
    transform 160ms var(--cc-ease-out),
    filter 160ms var(--cc-ease-out);
}

.call-chip[data-status='done'] .call-chip__glyph[data-state='in'] {
  color: var(--cc-done);
}

.call-chip[data-status='error'] .call-chip__glyph[data-state='in'] {
  color: var(--cc-error);
}

.call-chip__name,
.call-chip__arg,
.call-chip__timer {
  position: relative;
}

.call-chip__name {
  font-weight: 500;
}

.call-chip__arg {
  opacity: 0.72;
}

.call-chip__timer {
  min-width: 6ch;
  font-variant-numeric: tabular-nums;
  text-align: right;
  opacity: 0.5;
}

.call-chip__retry {
  position: absolute;
  inset: -5px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--cc-radius);
  background: transparent;
  appearance: none;
  cursor: pointer;
  outline: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.call-chip__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .call-chip[data-status='done'] .call-chip__fill {
    clip-path: inset(0 0 0 0);
    transition: background-color 120ms ease;
  }

  .call-chip__glyph {
    transform: none !important;
    filter: none !important;
  }

  .call-chip[data-pressed] {
    transform: none;
  }
}

